UPDATE products SET lead = 'Giữ tiền là giống phú quý (Aglaonema) lá thon dài, phiến xanh có mảng xanh nhạt dọc gân, gân giữa và cuống lá trắng. Cây chịu bóng, ít sâu bệnh, hợp đặt trong nhà, văn phòng. Tên gọi mang ý giữ tiền tài nên hay được chọn làm quà khai trương, tân gia.', updated_at = now() WHERE slug = 'giu-tien' AND lead = 'Giữ tiền là cây kiểng lá trồng chậu, lấy từ nhà vườn ở Làng hoa Sa Đéc. Cây hợp đặt trong nhà, văn phòng, nơi có ánh sáng tán xạ. Tên gọi mang ý giữ tiền tài nên cây hay được chọn làm quà khai trương, tân gia. Mô tả chi tiết về giống cây sẽ được bổ sung cùng hình ảnh.';
--> statement-breakpoint
